begin;
select set_config('qa.admin',(select id::text from profiles where peran='admin'limit 1),true);
select set_config('qa.wali',(select w.profile_id::text from wali_santri w join profiles p on p.id=w.profile_id where p.peran='wali'limit 1),true);
select set_config('qa.musyrif',(select id::text from profiles where peran='musyrif'limit 1),true);
select set_config('qa.guru',(select id::text from profiles where peran='pengajar_hifzh'limit 1),true);
select set_config('qa.anak',(select santri_id::text from wali_santri where profile_id=current_setting('qa.wali')::uuid limit 1),true);
select set_config('qa.asing',(select id::text from santri where id<>current_setting('qa.anak')::uuid limit 1),true);
select set_config('qa.data',jsonb_build_object('kunci',gen_random_uuid(),'judul','__qa_agenda__','mulai',now(),'selesai',now()+interval '1 hour','jenis','kegiatan','kelas_id',(select kelas_id from santri where id=current_setting('qa.anak')::uuid))::text,true);
select set_config('request.jwt.claim.sub',current_setting('qa.admin'),true);
set local role authenticated;
select set_config('qa.agenda',public.simpan_kalender(current_setting('qa.data')::jsonb)::text,true);
do $$begin
 if public.simpan_kalender(current_setting('qa.data')::jsonb)<>current_setting('qa.agenda')::uuid then raise exception 'Agenda retry berlipat';end if;
 begin perform public.simpan_kalender(current_setting('qa.data')::jsonb,current_setting('qa.agenda')::uuid,null);raise exception 'Revisi null lolos';exception when serialization_failure then null;end;
 begin perform public.simpan_kalender(current_setting('qa.data')::jsonb||jsonb_build_object('kunci',gen_random_uuid(),'selesai',now()-interval '1 hour'));raise exception 'Waktu agenda invalid lolos';exception when sqlstate '22023'then null;end;
end $$;
select set_config('qa.agenda_asing',public.simpan_kalender(current_setting('qa.data')::jsonb||jsonb_build_object('kunci',gen_random_uuid(),'kelas_id',(select kelas_id from santri where id=current_setting('qa.asing')::uuid)))::text,true);
insert into public.informasi_pondok(judul,isi,status)values('__qa_info__','Informasi uji sementara yang dibatalkan.','terbit');
select set_config('qa.info',(select id::text from informasi_pondok where judul='__qa_info__'),true);
select public.arsip_pondok('informasi',current_setting('qa.info')::uuid,1,false);
do $$begin if(select status from informasi_pondok where id=current_setting('qa.info')::uuid)<>'draf'then raise exception 'Informasi hapus tidak draf';end if;end$$;
select public.arsip_pondok('informasi',current_setting('qa.info')::uuid,2,true);
do $$begin if(select dihapus_pada from informasi_pondok where id=current_setting('qa.info')::uuid)is not null then raise exception 'Pemulihan info gagal';end if;end$$;
select set_config('qa.banner',(select id::text from banner_pondok order by urutan limit 1),true);
select public.arsip_pondok('banner',current_setting('qa.banner')::uuid,1,false);
select public.arsip_pondok('banner',current_setting('qa.banner')::uuid,2,true);
do $$begin if(select tayang from banner_pondok where id=current_setting('qa.banner')::uuid)then raise exception 'Pulihkan banner langsung tayang';end if;end$$;
select set_config('qa.path',current_setting('qa.admin')||'/'||gen_random_uuid()::text||'.webp',true);
insert into storage.objects(bucket_id,name)values('banner-pondok',current_setting('qa.path'));
select set_config('qa.upload',public.simpan_banner(jsonb_build_object('kunci',gen_random_uuid(),'judul','__qa_banner__','gambar_path',current_setting('qa.path'),'urutan',8,'tayang',true))::text,true);
reset role;
select set_config('request.jwt.claim.sub',current_setting('qa.musyrif'),true);
set local role authenticated;
select set_config('qa.health_data',jsonb_build_object('kunci',gen_random_uuid(),'santri_id',current_setting('qa.anak'),'tanggal',current_date,'keluhan','Keluhan uji sementara','tindakan','Penanganan dicatat petugas','status','dipantau')::text,true);
select set_config('qa.sehat',public.simpan_kesehatan(current_setting('qa.health_data')::jsonb)::text,true);
select set_config('qa.sehat_asing',public.simpan_kesehatan(current_setting('qa.health_data')::jsonb||jsonb_build_object('kunci',gen_random_uuid(),'santri_id',current_setting('qa.asing')))::text,true);
do $$begin
 if public.simpan_kesehatan(current_setting('qa.health_data')::jsonb)<>current_setting('qa.sehat')::uuid then raise exception 'Health retry berlipat';end if;
 begin perform public.simpan_kesehatan(current_setting('qa.health_data')::jsonb||jsonb_build_object('kunci',gen_random_uuid(),'tanggal',current_date+2));raise exception 'Health future lolos';exception when sqlstate '22023'then null;end;
 begin perform public.arsip_pondok('kesehatan',current_setting('qa.sehat')::uuid,1,false);raise exception 'Musyrif hapus lolos';exception when insufficient_privilege then null;end;
 begin perform public.simpan_kalender(current_setting('qa.data')::jsonb);raise exception 'Musyrif kelola agenda';exception when insufficient_privilege then null;end;
end$$;
select public.simpan_kesehatan(current_setting('qa.health_data')::jsonb||'{"status":"pulih"}'::jsonb,current_setting('qa.sehat')::uuid,1);
reset role;
select set_config('request.jwt.claim.sub',current_setting('qa.wali'),true);
set local role authenticated;
do $$begin
 if not exists(select 1 from kalender_pondok where id=current_setting('qa.agenda')::uuid)or exists(select 1 from kalender_pondok where id=current_setting('qa.agenda_asing')::uuid)then raise exception 'Scope kelas kalender salah';end if;
 if not exists(select 1 from kesehatan_santri where id=current_setting('qa.sehat')::uuid)or exists(select 1 from kesehatan_santri where id=current_setting('qa.sehat_asing')::uuid)then raise exception 'Kesehatan anak lain bocor';end if;
 if(select count(*)from kesehatan_riwayat where catatan_id=current_setting('qa.sehat')::uuid)<>2 then raise exception 'Jejak kesehatan salah';end if;
 if exists(select 1 from informasi_pondok where id=current_setting('qa.info')::uuid)then raise exception 'Informasi pulih draf bocor';end if;
 if exists(select 1 from banner_pondok where id=current_setting('qa.banner')::uuid)then raise exception 'Banner tidak tayang bocor';end if;
 if not exists(select 1 from storage.objects where name=current_setting('qa.path'))then raise exception 'Banner aktif tidak terbaca';end if;
 begin perform public.simpan_kesehatan(current_setting('qa.health_data')::jsonb);raise exception 'Wali menulis health';exception when insufficient_privilege then null;end;
 begin update kesehatan_santri set status='pulih';raise exception 'Direct health write lolos';exception when insufficient_privilege then null;end;
 begin perform public.simpan_banner('{}'::jsonb);raise exception 'Wali kelola banner';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('qa.guru'),true);
set local role authenticated;
do $$begin
 if exists(select 1 from kesehatan_santri)or exists(select 1 from kesehatan_riwayat)then raise exception 'Guru membaca kesehatan';end if;
 if(select count(*)from kalender_pondok where judul='__qa_agenda__')<>2 then raise exception 'Guru tidak melihat agenda kelas';end if;
 begin perform public.simpan_kesehatan(current_setting('qa.health_data')::jsonb);raise exception 'Guru menulis health';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('qa.admin'),true);
set local role authenticated;
select public.arsip_pondok('kesehatan',current_setting('qa.sehat')::uuid,2,false);
select public.arsip_pondok('kalender',current_setting('qa.agenda')::uuid,1,false);
select public.arsip_pondok('banner',current_setting('qa.upload')::uuid,1,false);
reset role;
select set_config('request.jwt.claim.sub',current_setting('qa.wali'),true);
set local role authenticated;
do $$begin
 if exists(select 1 from kesehatan_santri where id=current_setting('qa.sehat')::uuid)or exists(select 1 from kalender_pondok where id=current_setting('qa.agenda')::uuid)then raise exception 'Arsip bocor';end if;
 if exists(select 1 from storage.objects where name=current_setting('qa.path'))then raise exception 'Banner arsip file bocor';end if;
end$$;
reset role;
set local role anon;
do $$begin begin perform public.simpan_kesehatan('{}'::jsonb);raise exception 'Anon API';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
